operation.add:
$data['webmcp_catalog_js'] = '';
$data['webmcp_catalog_css'] = '';
$data['webmcp_catalog_search_url'] = '';
$data['webmcp_catalog_product_url'] = '';
$data['webmcp_catalog_cart_url'] = '';
$data['webmcp_catalog_cart_enabled'] = 0;
$data['webmcp_catalog_locale'] = '';
$data['webmcp_catalog_live_results'] = 0;
$data['webmcp_catalog_max_results'] = 6;
if ((int)$this->config->get('module_webmcp_catalog_status') === 1) {
    $ccwm_base = $this->config->get('config_ssl') ? $this->config->get('config_ssl') : $this->config->get('config_url');
    $ccwm_base = rtrim((string)$ccwm_base, '/') . '/';
    $ccwm_locale = isset($this->session->data['language']) ? strtolower((string)$this->session->data['language']) : strtolower((string)$this->config->get('config_language'));
    $ccwm_locale = preg_replace('/[^a-z0-9_.-]/i', '', $ccwm_locale);
    $data['webmcp_catalog_js'] = $ccwm_base . 'catalog/view/javascript/webmcp_catalog.js?v=110';
    $data['webmcp_catalog_css'] = $ccwm_base . 'catalog/view/stylesheet/webmcp_catalog.css?v=110';
    $data['webmcp_catalog_search_url'] = $this->url->link('extension/module/webmcp_catalog/search', '', true);
    $data['webmcp_catalog_product_url'] = $this->url->link('extension/module/webmcp_catalog/product', '', true);
    $data['webmcp_catalog_cart_url'] = $this->url->link('extension/module/webmcp_catalog/cart', '', true);
    $data['webmcp_catalog_cart_enabled'] = (int)$this->config->get('module_webmcp_catalog_cart_action');
    $data['webmcp_catalog_locale'] = $ccwm_locale;
    $data['webmcp_catalog_live_results'] = (int)$this->config->get('module_webmcp_catalog_live_results');
    $ccwm_max = (int)$this->config->get('module_webmcp_catalog_max_results');
    $data['webmcp_catalog_max_results'] = ($ccwm_max >= 1 && $ccwm_max <= 10) ? $ccwm_max : 6;
}

{% if webmcp_catalog_js %}
<link href="{{ webmcp_catalog_css }}" rel="stylesheet" media="screen">
<script src="{{ webmcp_catalog_js }}" defer data-webmcp-catalog="1" data-search-url="{{ webmcp_catalog_search_url }}" data-product-url="{{ webmcp_catalog_product_url }}" data-cart-url="{{ webmcp_catalog_cart_url }}" data-cart-enabled="{{ webmcp_catalog_cart_enabled }}" data-locale="{{ webmcp_catalog_locale }}" data-live-results="{{ webmcp_catalog_live_results }}" data-max-results="{{ webmcp_catalog_max_results }}"></script>
{% endif %}
